Here is the commit message:
pinctrl: mt7622: fix that pinctrl_claim_hogs cannot work

To allow claiming hogs by pinctrl, we cannot enable pinctrl until all
groups and functions are being added done. Also, it's necessary that
the corresponding gpiochip is being added when the pinctrl device is
enabled.

Cc: stable@vger.kernel.org
Fixes: d6ed93551320 ("pinctrl: mediatek: add pinctrl driver for MT7622 SoC")
Signed-off-by: Sean Wang <sean.wang@mediatek.com>
Signed-off-by: Linus Walleij <linus.walleij@linaro.org>

Here is the root cause:
The bug occurs because the pinctrl is being enabled before all groups and functions are added, which prevents `pinctrl_claim_hogs` from working correctly. This improper sequence of operations leads to the pinctrl not being fully configured when it is activated, causing functionality issues.

Here is the patch:

 static int mtk_pinctrl_probe(struct platform_device *pdev)
 {
 	struct resource *res;
 	struct mtk_pinctrl *hw;
 	const struct of_device_id *of_id =
 		of_match_device(mtk_pinctrl_of_match, &pdev->dev);
 	int err;

 	hw = devm_kzalloc(&pdev->dev, sizeof(*hw), GFP_KERNEL);
 	if (!hw)
 		return -ENOMEM;

 	hw->soc = of_id->data;

 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	if (!res) {
 		dev_err(&pdev->dev, "missing IO resource\n");
 		return -ENXIO;
 	}

 	hw->dev = &pdev->dev;
 	hw->base = devm_ioremap_resource(&pdev->dev, res);
 	if (IS_ERR(hw->base))
 		return PTR_ERR(hw->base);

 	/* Setup pins descriptions per SoC types */
 	mtk_desc.pins = hw->soc->pins;
 	mtk_desc.npins = hw->soc->npins;
 	mtk_desc.num_custom_params = ARRAY_SIZE(mtk_custom_bindings);
 	mtk_desc.custom_params = mtk_custom_bindings;
 #ifdef CONFIG_DEBUG_FS
 	mtk_desc.custom_conf_items = mtk_conf_items;
 #endif

-	hw->pctrl = devm_pinctrl_register(&pdev->dev, &mtk_desc, hw);
-	if (IS_ERR(hw->pctrl))
-		return PTR_ERR(hw->pctrl);
+	err = devm_pinctrl_register_and_init(&pdev->dev, &mtk_desc, hw,
+					     &hw->pctrl);
+	if (err)
+		return err;

 	/* Setup groups descriptions per SoC types */
 	err = mtk_build_groups(hw);
 	if (err) {
 		dev_err(&pdev->dev, "Failed to build groups\n");
 		return err;
 	}

 	/* Setup functions descriptions per SoC types */
 	err = mtk_build_functions(hw);
 	if (err) {
 		dev_err(&pdev->dev, "Failed to build functions\n");
 		return err;
 	}

+	/* For able to make pinctrl_claim_hogs, we must not enable pinctrl
+	 * until all groups and functions are being added one.
+	 */
+	err = pinctrl_enable(hw->pctrl);
+	if (err)
+		return err;
+
 	err = mtk_build_eint(hw, pdev);
 	if (err)
 		dev_warn(&pdev->dev,
 			 "Failed to add EINT, but pinctrl still can work\n");

+	/* Build gpiochip should be after pinctrl_enable is done */
 	err = mtk_build_gpiochip(hw, pdev->dev.of_node);
 	if (err) {
 		dev_err(&pdev->dev, "Failed to add gpio_chip\n");
 		return err;
 	}

 	platform_set_drvdata(pdev, hw);

 	return 0;
 }



